import { Controller, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 결재선을 수정할 수 있는 문서 상태는 '기안'뿐이다 (재기안 문서도 기안 상태로 돌아온다고 본다).
const EDITABLE_STATUS = '기안';

function positiveInt(v: unknown): number | null {
  if (typeof v === 'number' && Number.isInteger(v) && v > 0) {
    return v;
  }
  return null;
}

@Controller('api/v1')
export class FnSfr029113Xc9b6efController {
  // 가정: 본문은 { items: [{ approverId, lineGroup, sequenceNo }] } 형태로 받아 문서의 결재선 전체를 교체한다.
  @Put('/approval-documents/:approvalDocumentId/approval-lines')
  async replaceApprovalLines(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const documentId = req.params['approvalDocumentId'];
    if (!/^\d+$/.test(documentId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서 번호가 올바르지 않습니다.');
    }
    const raw = (data as Record<string, unknown>)['items'];
    if (!Array.isArray(raw)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재선 목록이 필요합니다.');
    }
    if (raw.length === 0) {
      throw new ApiError(422, 'APPROVER_REQUIRED', '결재자가 없는 결재선은 저장할 수 없습니다.');
    }
    const lines: { approverId: number; lineGroup: number; sequenceNo: number }[] = [];
    const seen = new Set<string>();
    for (const item of raw) {
      const row = (item && typeof item === 'object' ? item : {}) as Record<string, unknown>;
      const approverId = positiveInt(row['approverId']);
      const lineGroup = positiveInt(row['lineGroup']);
      const sequenceNo = positiveInt(row['sequenceNo']);
      if (approverId === null || lineGroup === null || sequenceNo === null) {
        throw new ApiError(400, 'VALIDATION_FAILED', '결재자, 결재선 구분, 결재 순서는 1 이상의 정수여야 합니다.');
      }
      const key = lineGroup + ':' + sequenceNo;
      if (seen.has(key)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '같은 결재선 구분 안에서 결재 순서가 중복되었습니다.');
      }
      seen.add(key);
      lines.push({ approverId, lineGroup, sequenceNo });
    }
    return transaction(async (db) => {
      const docs = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM approval_document WHERE approval_document_id = CAST(:documentId AS bigint)',
        { documentId },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '대상 결재문서를 찾을 수 없습니다.');
      }
      if (docs[0]['approvalStatus'] !== EDITABLE_STATUS) {
        throw new ApiError(409, 'APPROVAL_ALREADY_IN_PROGRESS', '결재가 시작된 문서의 결재선은 수정할 수 없습니다.');
      }
      for (const line of lines) {
        const found = await db.query(
          "SELECT employee_id FROM employee WHERE employee_id = CAST(:approverId AS bigint) AND employment_status = '재직'",
          { approverId: line.approverId },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'APPROVER_NOT_FOUND', '조직도에 없는 사용자는 결재자로 지정할 수 없습니다.');
        }
      }
      await db.execute(
        'DELETE FROM approval_line WHERE approval_document_id = CAST(:documentId AS bigint)',
        { documentId },
      );
      const items: unknown[] = [];
      for (const line of lines) {
        const inserted = await db.query(
          'INSERT INTO approval_line (approval_document_id, approver_id, line_group, sequence_no, created_at, updated_at) ' +
            'VALUES (CAST(:documentId AS bigint), CAST(:approverId AS bigint), CAST(:lineGroup AS integer), CAST(:sequenceNo AS integer), now(), now()) ' +
            'RETURNING approval_line_id AS "approvalLineId", approver_id AS "approverId", line_group AS "lineGroup", sequence_no AS "sequenceNo"',
          {
            documentId,
            approverId: line.approverId,
            lineGroup: line.lineGroup,
            sequenceNo: line.sequenceNo,
          },
        );
        items.push(inserted[0]);
      }
      return { items, page: 0, size: items.length, total: items.length };
    });
  }
}

