import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Band,
  DataTable,
  Drawer,
  Tiles,
  Form,
  Field,
  NumberInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

interface LineDraft {
  approverId: number | string;
  lineGroup: number | string;
  sequenceNo: number | string;
}

export default function FnSfr029113Xc9b6efPage({ role, notify }: PageProps) {
  const [documentId, setDocumentId] = useState<number | string>('');
  const [editing, setEditing] = useState<LineDraft[] | null>(null);

  const { data, error, reload } = useData<Page>(async () => {
    if (documentId === '') {
      return { items: [], page: 0, size: 0, total: 0 };
    }
    return call<Page>('GET', '/approval-lines', role, undefined, { approvalDocumentId: documentId });
  }, [documentId]);

  const rows: Row[] = data ? data.items : [];
  const groups = new Set(rows.map((r) => String(r.lineGroup))).size;
  const processed = rows.filter((r) => r.actionType).length;

  const openEdit = () => {
    const start: LineDraft[] = rows.map((r) => ({
      approverId: Number(r.approverId),
      lineGroup: Number(r.lineGroup),
      sequenceNo: Number(r.sequenceNo),
    }));
    setEditing(start.length > 0 ? start : [{ approverId: '', lineGroup: 1, sequenceNo: 1 }]);
  };

  const change = (index: number, patch: Partial<LineDraft>) => {
    setEditing((cur) => (cur ? cur.map((l, i) => (i === index ? { ...l, ...patch } : l)) : cur));
  };

  const submit = async () => {
    if (!editing || editing.length === 0) {
      throw new Error('결재자를 한 명 이상 지정해 주세요.');
    }
    for (const l of editing) {
      if (l.approverId === '' || l.lineGroup === '' || l.sequenceNo === '') {
        throw new Error('결재자, 결재선 구분, 결재 순서를 모두 입력해 주세요.');
      }
    }
    await call('PUT', '/approval-documents/' + documentId + '/approval-lines', role, {
      items: editing as unknown as Row[],
    });
    notify('결재선을 저장했습니다.');
    setEditing(null);
    reload();
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>결재문서</h2>
        <Field label="결재문서" required>
          <LookupSelect
            table="approval_document"
            role={role}
            value={documentId}
            onChange={setDocumentId}
            placeholder="문서 선택"
          />
        </Field>
      </section>
      <section className="box span-12">
        <h2>결재선 현황</h2>
        <Tiles
          items={[
            ['결재자 수', rows.length],
            ['결재선 수', groups],
            ['처리 완료', processed],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>결재선 목록</h2>
        {error ? <ErrorText text={error} /> : null}
        <Band total={rows.length}>
          {documentId !== '' ? (
            <button type="button" onClick={openEdit}>
              결재선 지정
            </button>
          ) : null}
        </Band>
        <DataTable
          rows={rows}
          empty="문서를 선택하면 결재선이 보입니다."
          columns={[
            { key: 'lineGroup', label: '결재선 구분' },
            { key: 'sequenceNo', label: '결재 순서' },
            {
              key: 'approverId',
              label: '결재자',
              render: (r) => <RefName table="employee" role={role} value={r.approverId} />,
            },
            { key: 'actionType', label: '처리 유형', render: (r) => <Badge value={r.actionType} /> },
            { key: 'opinion', label: '결재 의견' },
            {
              key: 'processedAt',
              label: '처리 일시',
              render: (r) => <DateText value={r.processedAt} time />,
            },
          ]}
        />
      </section>
      {editing ? (
        <Drawer title="결재선 지정" onClose={() => setEditing(null)}>
          <Form
            submit="저장"
            onSubmit={submit}
            note="결재가 시작된 문서의 결재선은 수정할 수 없습니다."
          >
            {editing.map((line, index) => (
              <div key={index}>
                <Field label="결재자" required>
                  <LookupSelect
                    table="employee"
                    role={role}
                    value={line.approverId}
                    onChange={(v) => change(index, { approverId: v })}
                    placeholder="결재자 선택"
                  />
                </Field>
                <Field label="결재선 구분" required>
                  <NumberInput value={line.lineGroup} onChange={(v) => change(index, { lineGroup: v })} />
                </Field>
                <Field label="결재 순서" required>
                  <NumberInput value={line.sequenceNo} onChange={(v) => change(index, { sequenceNo: v })} />
                </Field>
                <button
                  type="button"
                  onClick={() => setEditing(editing.filter((_, i) => i !== index))}
                >
                  삭제
                </button>
              </div>
            ))}
            <button
              type="button"
              onClick={() =>
                setEditing([...editing, { approverId: '', lineGroup: 1, sequenceNo: editing.length + 1 }])
              }
            >
              결재자 추가
            </button>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
